// SNP Reader MVP: deliberately static. Uploaded raw DNA never leaves this browser.
const catalog = [
  {id:'rs4988235',gene:'MCM6 / LCT',title:'Adult lactose digestion',category:'Nutrition',alleles:['A','G'],evidence:'Established population association',source:'https://medlineplus.gov/genetics/condition/lactose-intolerance/',detail:'This regulatory variant near LCT helps control whether lactase production continues after childhood. The A allele on the GRCh37 forward strand is associated with lactase persistence in many European populations.',interpret(g){return g.includes('A')?'At least one A allele is associated with continued lactase production into adulthood in populations where this marker has been validated.':'GG is associated with lactase non-persistence in many European populations, but other genetic variants and non-genetic causes also affect lactose digestion.'},caution:'This single marker is less informative across some ancestries. Symptoms and clinical evaluation matter more than this genotype alone.'},
  {id:'rs1800562',gene:'HFE',title:'Iron regulation (C282Y)',category:'Health',alleles:['A','G'],evidence:'Clinical gene association',source:'https://medlineplus.gov/genetics/condition/hereditary-hemochromatosis/',detail:'HFE helps regulate iron absorption. The A allele corresponds to the C282Y change on the forward strand.',interpret(g){const a=[...g].filter(x=>x==='A').length;return a===2?'AA indicates two copies of the HFE C282Y variant, associated with increased risk of hereditary hemochromatosis. Not everyone with this genotype develops iron overload.':a===1?'AG indicates one C282Y copy (carrier status). One copy alone usually does not cause classic HFE-related hemochromatosis.':'GG does not show the C282Y variant at this marker. Other HFE variants and other causes of iron overload are not ruled out.'},caution:'Do not diagnose or change iron intake based on a consumer raw-data call. Discuss concerns with a clinician; confirmation and iron studies may be appropriate.'}
];
const $=id=>document.getElementById(id);
let records=new Map(),mode='';
let inventory=null;
async function loadInventory(){
  try{
    const response=await fetch('myheritage_gsa_rsids.txt',{cache:'force-cache'});
    if(!response.ok)throw Error('Inventory unavailable');
    inventory=new Set((await response.text()).trim().split(/\r?\n/));
    $('inventory-status').textContent=`${inventory.size.toLocaleString()} rsIDs ready to search`;
    updateInventoryCount();
  }catch{$('inventory-status').textContent='Reference inventory could not load. Curated interpretations still work.'}
}
function updateInventoryCount(){if(inventory&&records.size)$('inventorymatched').textContent=[...records.keys()].filter(id=>inventory.has(id)).length.toLocaleString()}
function lookupInventory(){
  const id=$('inventory-search').value.trim().toLowerCase();
  if(!/^rs\d+$/.test(id)){$('inventory-status').textContent='Enter an rsID, for example rs4988235.';return}
  if(!inventory){$('inventory-status').textContent='Reference inventory is still loading.';return}
  const known=inventory.has(id),curated=catalog.some(c=>c.id===id);
  $('inventory-status').textContent=known?`${id} is in the MyHeritage GSA inventory.${curated?' A curated explanation is available.':' No curated interpretation yet.'}`:`${id} was not in this supplied GSA inventory. Another chip version may include it.`;
}
function splitCsv(line){const out=[];let val='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){val+='"';i++}else quote=!quote}else if(c===','&&!quote){out.push(val.trim());val=''}else val+=c}out.push(val.trim());return out}
function normalizeHeader(s){return s.toLowerCase().replace(/^#+/,'').trim().replace(/[^a-z0-9]/g,'')}
export function parseDNA(text){const map=new Map();let format='',skip=0;let header=null,sep=null,build='';const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/);for(const line of lines){const trim=line.trim();if(!trim)continue;if(/^#/.test(trim)){if(/build\s*3[78]|grch3[78]/i.test(trim)){const m=trim.match(/(?:build\s*|grch)(3[78])/i);if(m)build=m[1]}if(!/^(#?rsid[,\t ]|#?rsid\s+chromosome)/i.test(trim))continue}if(!sep)sep=trim.includes('\t')?'\t':trim.includes(',')?',':null;if(!sep)throw Error('Unrecognized layout: expected a tab- or comma-separated raw DNA file.');const cells=sep===','?splitCsv(trim.replace(/^#(?=rsid)/i,'')):trim.replace(/^#(?=rsid)/i,'').split('\t').map(x=>x.trim());const norm=cells.map(normalizeHeader);if(norm[0]==='rsid'&&norm.includes('chromosome')){header=norm;format=norm.includes('allele1')?'MyHeritage 5-column':sep===','?'MyHeritage CSV':'23andMe / TSV';continue}let id,chr,pos,geno;if(header){const get=(key)=>cells[header.indexOf(key)];id=get('rsid');chr=get('chromosome');pos=get('position');geno=header.includes('genotype')?get('genotype'):header.includes('result')?get('result'):header.includes('allele1')?String(get('allele1')||'')+String(get('allele2')||''):''}else if(cells.length>=4){[id,chr,pos,geno]=cells;format=sep===','?'CSV':'23andMe / TSV'}else{skip++;continue}if(!/^rs\d+$/i.test(id||'')){skip++;continue}const normalized=String(geno||'').toUpperCase().replace(/\s+/g,'');if(!/^(?:[ACGT]{1,2}|--|00|II|DD|ID|DI)$/.test(normalized)){skip++;continue}map.set(id.toLowerCase(),{id:id.toLowerCase(),chr,pos,genotype:normalized})}if(!map.size)throw Error('No recognized rsID genotype rows found. Check that this is an unmodified 23andMe or MyHeritage raw export.');return{records:map,format,build,skipped:skip}}
async function unzip(file){const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length<30||bytes[0]!==0x50||bytes[1]!==0x4b)throw Error('This ZIP archive is not readable.');let offset=0;while(offset+30<bytes.length){const view=new DataView(bytes.buffer,bytes.byteOffset+offset);if(view.getUint32(0,true)!==0x04034b50)break;const flags=view.getUint16(6,true),method=view.getUint16(8,true),size=view.getUint32(18,true),nameLen=view.getUint16(26,true),extraLen=view.getUint16(28,true);const name=new TextDecoder().decode(bytes.slice(offset+30,offset+30+nameLen));const start=offset+30+nameLen+extraLen;if((flags&8)||size===0)throw Error('This ZIP format is unsupported. Please extract its TXT or CSV file first.');if(/\.(txt|csv|tsv)$/i.test(name)&&!name.startsWith('__MACOSX')){const compressed=bytes.slice(start,start+size);if(method===0)return new TextDecoder().decode(compressed);if(method===8){if(typeof DecompressionStream==='undefined')throw Error('Please extract the ZIP first; this browser cannot decompress it.');try{const output=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return await new Response(output).text()}catch{throw Error('Could not decompress ZIP here. Please extract the TXT or CSV file and upload that instead.')}}}offset=start+size}throw Error('No supported raw DNA TXT or CSV file found in ZIP. Try extracting it first.')}
function safe(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function matches(){return catalog.map(c=>({...c,call:records.get(c.id)}))}
function draw(){
  const term=$('search').value.toLowerCase().trim(),category=$('filter').value;
  const filtered=matches().filter(c=>(category==='all'||c.category===category)&&[c.id,c.gene,c.title,c.category].join(' ').toLowerCase().includes(term));
  if(!filtered.length){$('cards').innerHTML='<div class="empty">No catalog entries match this search.</div>';return}
  const rows=filtered.map(c=>{
    const g=c.call?.genotype||'';
    const valid=g&&g!=='--'&&g!=='00'&&g.length===2&&[...g].every(x=>c.alleles.includes(x));
    const meaning=valid?c.interpret(g):c.call?'No-call or allele representation that cannot be interpreted safely.':'Not present in the uploaded file; this marker may not have been tested.';
    return `<tr><td><strong>${safe(c.id)}</strong><span class="td-sub">${safe(c.gene)}</span></td><td><span class="topic-title">${safe(c.title)}</span><span class="tag">${safe(c.category)}</span></td><td><span class="genotype-chip">${safe(g||'—')}</span><span class="td-sub">${valid?'Called':c.call?'Unresolved':'Not found'}</span></td><td class="interpretation-cell"><div class="interpretation-main">${safe(meaning)}</div><details><summary>Evidence and limitations</summary><p>${safe(c.detail)}</p><p class="evidence-caution">ⓘ ${safe(c.caution)}</p><small>Evidence: ${safe(c.evidence)}</small><div class="table-links"><a href="${c.source}" target="_blank" rel="noopener">NIH evidence ↗</a><a href="https://www.ncbi.nlm.nih.gov/snp/${c.id}" target="_blank" rel="noopener">dbSNP ↗</a><a href="https://www.ncbi.nlm.nih.gov/clinvar/?term=${c.id}" target="_blank" rel="noopener">ClinVar ↗</a></div></details></td></tr>`;
  }).join('');
  $('cards').innerHTML=`<div class="result-table-scroll"><table class="result-table"><thead><tr><th>SNP / Gene</th><th>Research topic</th><th>Genotype</th><th>Meaning & evidence</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}
function show(result,label){records=result.records;mode=label;$('results').hidden=false;$('error').hidden=true;$('total').textContent=records.size.toLocaleString();$('annotated').textContent=catalog.filter(c=>records.has(c.id)).length;$('nocalls').textContent=[...records.values()].filter(x=>x.genotype==='--'||x.genotype==='00').length.toLocaleString();updateInventoryCount();$('result-summary').textContent=`${label} · ${result.format}${result.build?' · Genome build '+result.build:''}. Showing curated interpretations; the marker inventory is separate.`;$('search').value='';$('filter').value='all';draw();$('results').scrollIntoView({behavior:'smooth',block:'start'})}
async function handle(file){if(!file)return;try{if(file.size>80*1024*1024)throw Error('File is over the 80 MB safety limit. Try the original compressed export or smaller raw text file.');const text=/\.zip$/i.test(file.name)?await unzip(file):await file.text();const result=parseDNA(text);show(result,file.name)}catch(e){$('error').textContent=e.message;$('error').hidden=false;$('error').scrollIntoView({behavior:'smooth',block:'center'})}}
const demo=`# Synthetic sample, forward strand build 37\nrsid\tchromosome\tposition\tgenotype\nrs4988235\t2\t136608646\tAG\nrs1800562\t6\t26093141\tAG\nrs999999\t1\t123456\tAA`;
$('inventory-button').addEventListener('click',lookupInventory);
$('inventory-search').addEventListener('keydown',e=>{if(e.key==='Enter')lookupInventory()});
loadInventory();
$('browse').addEventListener('click',e=>{e.stopPropagation();$('file').click()});$('drop').addEventListener('click',()=> $('file').click());$('drop').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('file').click()}});$('file').addEventListener('change',e=>handle(e.target.files[0]));['dragenter','dragover'].forEach(t=>$('drop').addEventListener(t,e=>{e.preventDefault();$('drop').classList.add('drag')}));['dragleave','drop'].forEach(t=>$('drop').addEventListener(t,e=>{e.preventDefault();$('drop').classList.remove('drag')}));$('drop').addEventListener('drop',e=>handle(e.dataTransfer.files[0]));$('demo').addEventListener('click',()=>show(parseDNA(demo),'Fictional sample genome'));$('search').addEventListener('input',draw);$('filter').addEventListener('change',draw);$('clear').addEventListener('click',()=>{records.clear();mode='';$('file').value='';$('results').hidden=true;$('upload').scrollIntoView({behavior:'smooth'})});$('export').addEventListener('click',()=>{const rows=[['rsID','gene','topic','genotype','interpretation','evidence_source']];for(const c of matches()){const g=c.call?.genotype||'';const valid=g.length===2&&[...g].every(a=>c.alleles.includes(a));rows.push([c.id,c.gene,c.title,g,valid?c.interpret(g):'Not interpretable / not present',c.source])}const csv=rows.map(r=>r.map(s=>'"'+String(s).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='snp-reader-curated-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
